"""Explain failure contracts and generic barrier layers in plain Korean."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1629': ('어떤 가게가 약속보다 선물을 더 줬다고 모든 가게에서도 받을 수 있는 것은 아니에요. 코드 한 곳의 추가 동작과 공통으로 보장하는 규칙도 나누어 봐요.', '특정 도우미의 실패 후 동작과 공통 API의 약속을 구별합니다.', '결과 false 저장 → acquire 장벽 호출 → false 반환을 적으세요. 옆에는 이 도우미에서 확인한 흐름이라고 표시하세요.', ['API는 다른 코드가 기능을 부를 때 쓰는 이름과 사용 약속이에요. 내부 도우미는 그 기능을 만드는 데 사용하는 작은 코드 조각이에요. CPU 종류에 따라 같은 API를 다른 내부 코드로 구현할 수 있어요.', '__atomic_op_acquire는 relaxed 연산의 결과를 __ret에 저장해요. bool은 참 또는 거짓을 나타내는 자료형이에요. 그 결과가 false, 즉 거짓이어도 바로 다음 줄의 acquire 장벽을 호출해요.', '본문에는 성공했을 때만 장벽을 호출하라는 if가 없어요. 따라서 이 도우미를 실제로 거친다면 결과 저장 → 장벽 → 결과 반환의 순서예요. false를 반환하는 것과 장벽을 생략하는 것은 같은 일이 아니에요.', 'full 도우미도 앞 장벽 → 연산 → 뒤 장벽 → 반환으로 이어져요. 결과가 실패인지 검사해서 뒤 장벽을 건너뛰는 분기가 없어요. 이런 설명은 지금 읽은 도우미의 제어 흐름에 관한 것이에요.', '예를 들어 try 비교 연산이 예상 4와 실제 5를 비교하면 실패하고, 예상 값을 담는 칸은 관찰한 5로 바뀔 수 있어요. 실패라고 모든 관련 칸이 그대로라는 뜻은 아니에요. 실패 결과, 예상 값 갱신, 장벽 호출을 따로 기록하면 덜 헷갈려요.', '하지만 공개 cmpxchg_acquire 약속은 실패했을 때 acquire 순서를 보장하지 않아요. 어떤 구현이 더 강하게 동작하는 것을 보았다고 다른 CPU에서도 그 추가 동작에 의존하면 안 돼요. 여러 CPU에서 쓸 코드는 공통으로 약속한 범위에 맞춰 작성해야 해요.'], [('이 내부 acquire 도우미는 결과가 false이면 장벽을 건너뛰나요?', ['네. 성공인 경우에만 장벽을 호출해요', '아니요. 결과를 저장한 다음 장벽을 호출해요'], '정답은 두 번째예요. 본문에는 결과를 검사하는 if가 없어요. false도 __ret에 보관하고 장벽 뒤에 돌려줘요. 결과가 실패라는 사실만으로 뒤 문장이 생략되지는 않아요.'), ('이 도우미에서 장벽을 보았으므로 모든 cmpxchg_acquire의 실패에도 acquire 순서를 기대해도 되나요?', ['아니요. 공통 API가 약속한 실패 규칙을 따라야 해요', '네. 한 도우미가 모든 CPU의 구현을 대표해요'], '정답은 첫 번째예요. CPU별로 다른 구현을 선택할 수 있고 공개 약속은 실패 시 acquire를 보장하지 않아요. 특정 구현의 추가 동작을 모든 구현의 필수 동작으로 넓힐 수 없어요.')]), 'os1630': ('설계도를 정리하는 사람과 실제 물건을 만드는 사람은 서로 달라요. 컴파일러가 명령을 정리하는 순서와 CPU·장치가 일을 관찰하는 순서도 나누어 생각해야 해요.', '공통 장벽의 기본값과 컴파일러·CPU·장치의 역할을 구별합니다.', '컴파일러: 코드 번역 / CPU: 명령 실행 / 장치: 입출력 처리를 세 칸에 적으세요. mb의 기본 연결인 barrier()는 컴파일러 쪽이라고 표시하세요.', ['asm-generic/barrier.h의 generic은 여러 환경에서 공통으로 쓸 바탕이라는 뜻이에요. 새 CPU 계열에서 Linux를 실행하도록 옮기는 일을 port라고 해요. 이 파일은 그런 작업을 시작할 때 참고하는 기본 정의를 제공해요.', 'mb는 메모리 장벽 이름이고 rmb와 wmb는 각각 읽기 쪽과 쓰기 쪽 장벽 이름이에요. 이 파일에서 mb가 아직 정의되지 않았으면 mb()를 barrier()에 연결해요. #ifndef mb는 바로 그 조건이에요.', '컴파일러는 C 코드를 기계가 실행할 명령으로 번역하면서 순서를 바꾸는 최적화를 할 수 있어요. barrier()는 이 컴파일러가 메모리 접근을 장벽 너머로 옮기는 것을 제한해요. 이것을 컴파일러 장벽이라고 해요.', 'CPU도 명령을 처리하는 내부 방식이 있고, 장치도 입출력 요청을 처리하는 방식이 있어요. 컴파일러에게 순서를 지키라고 말했다는 사실만으로 그 모든 관찰 순서를 해결한 것은 아니에요. 해당 CPU와 장치에 필요한 실제 장벽 구현이 맞게 연결되어야 해요.', 'rmb와 wmb도 따로 정의되지 않으면 여기서는 mb로 연결돼요. 예를 들어 기본 연결만 따라가면 rmb → mb → barrier가 돼요. 그러나 CPU별 헤더가 적절한 정의를 제공했다면 그 다른 경로를 사용할 수 있어요.', '그러므로 새 CPU에 이 파일을 가져다 놓는 것만으로 순서 처리가 모두 완성되지는 않아요. 이름이 mb라고 모든 CPU에서 같은 명령이나 같은 시간이 드는 것도 아니에요. 기본 정의와 해당 CPU의 실제 정의를 함께 읽어야 해요.'], [('mb가 따로 정의되지 않았을 때 이 공통 헤더는 mb()를 무엇에 연결하나요?', ['모든 CPU에 공통인 장치 메모리 비우기 명령에 연결해요', '컴파일러 장벽인 barrier()에 연결해요'], '정답은 두 번째예요. #ifndef mb 아래의 정의가 mb()를 barrier()로 바꿔요. 이 기본 연결을 모든 CPU의 장치 처리 명령이라고 해석하면 안 돼요.'), ('컴파일러 장벽이 있다는 사실만으로 모든 장치의 접근 순서도 보장된다고 할 수 있나요?', ['아니요. CPU와 장치에 맞는 구현과 사용 규칙도 확인해야 해요', '네. 컴파일러와 장치는 같은 일을 하므로 충분해요'], '정답은 첫 번째예요. 컴파일러는 코드를 번역하고 CPU와 장치는 실제 작업을 수행해요. 번역 단계의 순서 제한과 하드웨어가 제공하는 순서 보장은 구별해야 해요.')]), 'os1631': ('한 안내서를 두 종류의 독자가 볼 때, 각자 읽을 수 있는 부분만 골라 줄 수 있어요. 이 헤더도 C 코드와 어셈블리 코드가 보는 부분을 나눠요.', '전처리 언어 경계와 nop의 의미를 이해합니다.', '__ASSEMBLY__ 있음 → C 영역 제외, 없음 → C 영역 포함을 그리세요. nop 옆에는 수면이나 메모리 장벽 아님이라고 적으세요.', ['C와 어셈블리는 서로 다른 코드 언어예요. C에는 자료형과 함수 같은 문법이 있고, 어셈블리는 CPU 명령에 가까운 내용을 적어요. 어셈블리 쪽에서 C의 문법을 그대로 읽게 하면 문제가 될 수 있어요.', '헤더의 #ifndef __ASSEMBLY__는 __ASSEMBLY__라는 이름이 정의되지 않은 경우에만 안쪽 내용을 포함하라는 뜻이에요. 어셈블리용으로 그 이름을 정의하고 전처리하면 C 정의 영역은 제외돼요.', '전처리는 컴파일 전에 필요한 코드 조각을 고르는 단계예요. 프로그램이 실행되다가 C 작업인지 어셈블리 작업인지 매번 확인하는 조건문이 아니에요. 이 조건은 코드가 준비되는 단계에 적용돼요.', 'nop은 no operation의 줄임말이에요. 여기서는 nop이 따로 정의되지 않았을 때 asm volatile("nop")로 정의해요. C 안에 어셈블리 명령을 적는 형태예요. volatile은 여기서 이 어셈블리를 단순히 불필요하다고 제거하지 않도록 알리는 역할을 해요.', 'nop 한 번을 실행하는 것과 메모리 접근 순서를 보장하는 것은 달라요. asm volatile이라는 글자만으로 완전한 메모리 장벽이 되지도 않아요. 또 nop은 기다리는 작업 목록에 현재 작업을 넣거나 다른 작업에게 CPU를 넘기는 schedule 호출도 아니에요.', '따라서 nop을 보고 1초 동안 잠든다고 설명하면 틀려요. 이 코드에는 초 단위 시간을 받거나 확인하는 부분이 없어요. CPU 명령 실행, 순서 장벽, 잠드는 대기는 각각 무엇을 약속하는지 구별하세요.'], [('어셈블리용으로 __ASSEMBLY__를 정의하면 이 헤더의 C 정의 영역은 어떻게 되나요?', ['어셈블리가 C 자료형을 모두 그대로 해석해요', '전처리 조건에 따라 C 정의 영역을 제외해요'], '정답은 두 번째예요. #ifndef는 그 이름이 정의되지 않았을 때만 안쪽을 포함해요. 어셈블리가 C 문법을 자동으로 이해하게 만드는 장치는 아니에요.'), ('nop 한 번은 완전한 메모리 장벽이나 작업을 잠들게 하는 schedule과 같은 기능인가요?', ['아니요. 각각 다른 기능이에요', '네. nop이 작업을 기다림 목록에 등록해요'], '정답은 첫 번째예요. nop은 no operation 명령이고 이 정의에는 기다림 목록 등록이나 수면 호출이 없어요. 순서 보장과 정해진 시간의 대기를 nop에 덧붙여 해석하지 마세요.')]), 'os1632': ('안전 검사 담당자에게 지금 어떤 절차를 하는지 알린 다음, 실제 절차를 수행하는 모습을 생각해 보세요. 알리는 일과 실제 동작은 서로 다른 역할이에요.', 'KCSAN에 순서를 알리는 호출과 실제 장벽 구현을 구별합니다.', 'mb 호출 → kcsan_mb로 검사 도구에 알림 → __mb 실행을 그리세요. rmb와 wmb도 같은 방식으로 연결하세요.', ['KCSAN은 커널에서 여러 실행 흐름이 같은 데이터에 접근할 때 생기는 문제를 찾는 데 쓰는 검사 도구예요. 계측은 이런 검사에 필요한 정보를 코드에서 알려 주는 장치를 붙이는 일이에요.', 'CPU별 코드가 __mb를 제공하면 공통 헤더는 mb() 안에서 kcsan_mb()를 먼저 부르고 __mb()를 다음에 불러요. 앞의 호출은 검사 도구에 순서를 알리는 역할이고 뒤의 호출은 해당 CPU의 기반 장벽 구현이에요.', '이름 앞의 __ 두 개는 여기서 내부 기반 이름과 공개 이름을 나누는 데 쓰여요. __라는 글자 자체가 장벽을 만들어 주는 것은 아니에요. #ifdef __mb가 있는지 확인하고 실제 정의를 따라가야 해요.', 'rmb도 __rmb가 있으면 kcsan_rmb → __rmb 순서이고, wmb도 kcsan_wmb → __wmb 순서예요. 읽기와 쓰기에 맞는 알림과 기반 동작을 각각 연결해요.', 'do { ... } while (0)은 여러 문장을 한 문장처럼 묶어 쓰는 매크로 형태예요. 먼저 본문을 한 번 실행하고 조건 0이 거짓이므로 반복하지 않아요. 따라서 이 코드가 끝없이 장벽을 실행하는 반복문이라는 뜻은 아니에요.', 'KCSAN에 알렸다고 실제 __mb 호출을 빼도 되는 것은 아니에요. 반대로 도우미 호출 순서를 종이에 확인했다고 실제 검사 도구를 실행하거나 모든 CPU의 관찰 순서를 시험한 것도 아니에요. 검사 알림, 기반 구현, 검증 결과의 범위를 나누어 읽으세요.'], [('__mb가 제공된 경우 공통 mb()는 무엇을 먼저 호출하나요?', ['__mb 뒤에 반드시 작업을 잠들게 하는 함수를 호출해요', 'kcsan_mb()를 먼저 호출해요'], '정답은 두 번째예요. 본문은 kcsan_mb(); __mb(); 순서예요. 검사 도구에 순서를 알린 다음 실제 기반 장벽으로 이어지며 수면 호출은 없어요.'), ('KCSAN에 알리는 호출이 실제 CPU별 장벽인 __mb를 대신하나요?', ['아니요. 이 코드에서는 두 역할을 따로 호출해요', '네. 알림만 있으면 __mb는 항상 없어도 돼요'], '정답은 첫 번째예요. 검사 도구가 순서를 이해하도록 알리는 일과 그 순서를 실제로 제공하는 구현은 달라요. 원문도 두 호출을 차례로 두고 있어요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_403.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
